W = H = 1024

# ---------------------------------------------------------------- canvas

class Canvas:
    def __init__(self, w, h, color=(255, 255, 255)):
        self.w, self.h = w, h
        self.px = bytearray(color * (w * h))

    def _i(self, x, y):
        return (y * self.w + x) * 3

    def put(self, x, y, color, alpha=255):
        if 0 <= x < self.w and 0 <= y < self.h:
            i = self._i(x, y)
            if alpha >= 255:
                self.px[i:i + 3] = bytes(color)
            elif alpha > 0:
                a = alpha / 255.0
                for k in range(3):
                    self.px[i + k] = int(self.px[i + k] * (1 - a) + color[k] * a)

    def get(self, x, y):
        i = self._i(int(x), int(y))
        return self.px[i], self.px[i + 1], self.px[i + 2]

    def rect(self, x0, y0, x1, y1, color, alpha=255):
        for y in range(max(0, y0), min(self.h, y1)):
            for x in range(max(0, x0), min(self.w, x1)):
                self.put(x, y, color, alpha)

    def line(self, x0, y0, x1, y1, color, width=1, alpha=255):
        steps = max(abs(x1 - x0), abs(y1 - y0), 1)
        r = width // 2
        for s in range(steps + 1):
            x = x0 + (x1 - x0) * s / steps
            y = y0 + (y1 - y0) * s / steps
            for dy in range(-r, r + 1):
                for dx in range(-r, r + 1):
                    self.put(int(round(x)) + dx, int(round(y)) + dy, color, alpha)

    def circle(self, cx, cy, r, color, width=1, alpha=255):
        steps = max(24, int(2 * math.pi * r))
        for s in range(steps + 1):
            t = 2 * math.pi * s / steps
            x = cx + r * math.cos(t)
            y = cy + r * math.sin(t)
            for dy in range(-(width // 2), width // 2 + 1):
                for dx in range(-(width // 2), width // 2 + 1):
                    self.put(int(round(x)) + dx, int(round(y)) + dy, color, alpha)

    def ellipse(self, cx, cy, rx, ry, color, width=1, alpha=255):
        steps = max(24, int(2 * math.pi * max(rx, ry)))
        for s in range(steps + 1):
            t = 2 * math.pi * s / steps
            x = cx + rx * math.cos(t)
            y = cy + ry * math.sin(t)
            for dy in range(-(width // 2), width // 2 + 1):
                for dx in range(-(width // 2), width // 2 + 1):
                    self.put(int(round(x)) + dx, int(round(y)) + dy, color, alpha)

    def blit_rgb(self, data, sw, sh, dx, dy, alpha=255):
        for y in range(sh):
            for x in range(sw):
                i = (y * sw + x) * 3
                self.put(dx + x, dy + y,
                         (data[i], data[i + 1], data[i + 2]), alpha)

    def blit_rotated(self, src, cx, cy, angle_deg, alpha=255):
        """Rotate src around its centre and blend it onto this canvas."""
        a = math.radians(angle_deg)
        ca, sa = math.cos(a), math.sin(a)
        hw, hh = src.w / 2.0, src.h / 2.0
        rad = math.hypot(hw, hh)
        x0, x1 = int(cx - rad), int(cx + rad)
        y0, y1 = int(cy - rad), int(cy + rad)
        for dy in range(y0, y1):
            for dx in range(x0, x1):
                rx, ry = dx - cx, dy - cy
                sx = rx * ca + ry * sa + hw
                sy = -rx * sa + ry * ca + hh
                if 0 <= sx < src.w - 1 and 0 <= sy < src.h - 1:
                    c = src.get(sx, sy)
                    self.put(dx, dy, c, alpha)


# ---------------------------------------------------------------- fonts

_FONT_CACHE = {}


def _font(key):
    if key not in _FONT_CACHE:
        f = FONTS[key]
        raw = zlib.decompress(base64.b85decode(f["data"]))
        _FONT_CACHE[key] = (f, raw)
    return _FONT_CACHE[key]


def text_width(key, s, tracking=0.0):
    f, _ = _font(key)
    w = sum(f["glyphs"][ch][0] for ch in s)
    if len(s) > 1:
        w += tracking * (len(s) - 1)
    return w


def draw_text(cv, x, y_base, s, key, color, tracking=0.0, alpha=255):
    """Draw s with the pen at (x, y_base) on the baseline. Returns end x."""
    f, raw = _font(key)
    fw = f["w"]
    pen = float(x)
    for ch in s:
        adv, ox, oy, gw, gh, ax, ay = f["glyphs"][ch]
        if gw and gh:
            dx = int(round(pen)) + ox
            dy = y_base - f["ascent"] + oy
            for gy in range(gh):
                base = (ay + gy) * fw + ax
                for gx in range(gw):
                    v = raw[base + gx]
                    if v:
                        cv.put(dx + gx, dy + gy, color,
                               (v * alpha) // 255)
        pen += adv + tracking
    return pen


def draw_text_center(cv, cx, y_base, s, key, color, tracking=0.0, alpha=255):
    w = text_width(key, s, tracking)
    return draw_text(cv, cx - w / 2.0, y_base, s, key, color, tracking, alpha)


# ---------------------------------------------------------------- png out

def write_png(cv, path):
    def chunk(tag, data):
        c = struct.pack(">I", len(data)) + tag + data
        c += struct.pack(">I", zlib.crc32(tag + data) & 0xFFFFFFFF)
        return c

    raw = bytearray()
    stride = cv.w * 3
    for y in range(cv.h):
        raw.append(0)
        raw += cv.px[y * stride:(y + 1) * stride]
    png = b"\x89PNG\r\n\x1a\n"
    png += chunk(b"IHDR", struct.pack(">IIBBBBB", cv.w, cv.h, 8, 2, 0, 0, 0))
    png += chunk(b"IDAT", zlib.compress(bytes(raw), 9))
    png += chunk(b"IEND", b"")
    with open(path, "wb") as fh:
        fh.write(png)
    return len(png)


# ---------------------------------------------------------------- helpers

INK = (24, 28, 34)          # field ink, near-black blue
GREEN = (18, 66, 44)        # Vessalian green
GREEN_SOFT = (84, 118, 100)
LABEL = (96, 100, 96)       # grey field labels
BLUE_INK = (38, 62, 138)    # stamp ink blue
RED_INK = (168, 44, 40)     # stamp ink red
TEAL_INK = (20, 104, 110)   # stamp ink teal
PAPER = (246, 243, 233)


def mrz_check(field):
    weights = (7, 3, 1)
    total = 0
    for i, ch in enumerate(field):
        if ch.isdigit():
            v = int(ch)
        elif ch == "<":
            v = 0
        else:
            v = ord(ch) - 55
        total += v * weights[i % 3]
    return str(total % 10)


def guilloche(cv, cx, cy, r_max, color, rings=26, alpha=15):
    for k in range(rings):
        r = 8 + (r_max - 8) * k / max(1, rings - 1)
        steps = int(2 * math.pi * r)
        wob = 2.5 + 1.5 * math.sin(k * 1.7)
        for s in range(steps):
            t = 2 * math.pi * s / steps
            rr = r + wob * math.sin(3 * t + k * 0.9)
            x = int(round(cx + rr * math.cos(t)))
            y = int(round(cy + rr * math.sin(t) * 0.82))
            cv.put(x, y, color, alpha)


def emblem(cv, cx, cy, r):
    """Vessalia's arms: an anchor over waves, in a ring."""
    cv.circle(cx, cy, r, GREEN, 2)
    cv.circle(cx, cy, r - 3, GREEN, 1)
    # anchor
    cv.line(cx, cy - r + 10, cx, cy + r - 16, GREEN, 2)
    cv.circle(cx, cy - r + 13, 3, GREEN, 2)
    cv.line(cx - 8, cy - r + 18, cx + 8, cy - r + 18, GREEN, 2)
    for sgn in (-1, 1):
        for s in range(11):
            t = s / 10.0
            x = cx + sgn * (2 + 10 * t)
            y = cy + r - 16 - 8 * math.sin(t * math.pi * 0.62)
            cv.put(int(round(x)), int(round(y)), GREEN)
            cv.put(int(round(x)), int(round(y)) + 1, GREEN)
    # waves
    for row, yy in enumerate((cy + r - 12, cy + r - 8)):
        for x in range(cx - 13, cx + 14):
            y = yy + int(round(1.6 * math.sin((x - cx) / 3.4 + row * 1.9)))
            cv.put(x, y, GREEN)


def stamp_layer(w, h):
    return Canvas(w, h, (255, 255, 255))


def erode(cv, rng, keep=0.93):
    """Knock random specks out of a stamp layer so the ink looks stamped."""
    for y in range(cv.h):
        for x in range(cv.w):
            i = (y * cv.w + x) * 3
            if cv.px[i] < 250 and rng.random() > keep:
                cv.px[i:i + 3] = b"\xff\xff\xff"


def rect_stamp(lines, key_big, key_small, color, w, h, oval=False):
    """A border-stamp drawn in solid ink on a white layer (white = no ink
    once blended by luminance in blit_stamp)."""
    lay = Canvas(w, h, (255, 255, 255))
    if oval:
        lay.ellipse(w // 2, h // 2, w // 2 - 3, h // 2 - 3, color, 3)
        lay.ellipse(w // 2, h // 2, w // 2 - 8, h // 2 - 8, color, 1)
    else:
        for x in range(3, w - 3):
            for t in range(3):
                lay.put(x, 3 + t, color)
                lay.put(x, h - 4 - t, color)
        for y in range(3, h - 3):
            for t in range(3):
                lay.put(3 + t, y, color)
                lay.put(w - 4 - t, y, color)
    n = len(lines)
    total = n * 20 - 4
    y = h // 2 - total // 2 + 15
    for i, ln in enumerate(lines):
        key = key_big if i == 0 else key_small
        draw_text_center(lay, w // 2, y, ln, key, color)
        y += 20
    return lay


def blit_stamp(cv, lay, cx, cy, angle, rng, strength=205):
    """Blend a stamp layer by ink darkness (white stays paper)."""
    erode(lay, rng)
    a = math.radians(angle)
    ca, sa = math.cos(a), math.sin(a)
    hw, hh = lay.w / 2.0, lay.h / 2.0
    rad = math.hypot(hw, hh)
    for dy in range(int(cy - rad), int(cy + rad)):
        for dx in range(int(cx - rad), int(cx + rad)):
            rx, ry = dx - cx, dy - cy
            sx = rx * ca + ry * sa + hw
            sy = -rx * sa + ry * ca + hh
            if 0 <= sx < lay.w and 0 <= sy < lay.h:
                r, g, b = lay.get(sx, sy)
                dark = 255 - (r + g + b) // 3
                if dark > 8:
                    cv.put(dx, dy, (r, g, b), (dark * strength) // 255)


# ---------------------------------------------------------------- spread

def field(cv, x, y, label, value, key="sans16", vcolor=INK):
    draw_text(cv, x, y, label.upper(), "sans10", LABEL, tracking=0.6)
    draw_text(cv, x, y + 19, value, key, vcolor)


def data_page(cv, rng):
    # header
    emblem(cv, 256, 58, 26)
    draw_text_center(cv, 256, 122, "REPUBLIC OF VESSALIA", "serif30", GREEN,
                     tracking=1.0)
    draw_text_center(cv, 256, 146, "REPUBLIKA VESSALIA", "serif15", GREEN,
                     tracking=3.0)
    cv.line(40, 158, 472, 158, GREEN, 2)
    cv.line(40, 162, 472, 162, GREEN, 1)
    draw_text_center(cv, 256, 190, "PASSPORT", "sansb21", GREEN, tracking=7.0)
    draw_text_center(cv, 256, 208, "PASSAVORT", "sans11", GREEN_SOFT,
                     tracking=5.0)

    # type / code / number
    field(cv, 40, 228, "Type", "P", "sansb17")
    field(cv, 120, 228, "Code", "VES", "sansb17")
    field(cv, 250, 228, "Passport No.", "V4819207", "sansb17")

    # portrait
    raw = zlib.decompress(base64.b85decode(PORTRAIT_DATA))
    cv.blit_rgb(raw, PORTRAIT_W, PORTRAIT_H, 40, 268)
    x0, y0 = 39, 267
    x1, y1 = 40 + PORTRAIT_W, 268 + PORTRAIT_H
    cv.line(x0, y0, x1, y0, (110, 114, 108), 1)
    cv.line(x0, y1, x1, y1, (110, 114, 108), 1)
    cv.line(x0, y0, x0, y1, (110, 114, 108), 1)
    cv.line(x1, y0, x1, y1, (110, 114, 108), 1)
    guilloche(cv, 225, 495, 26, GREEN_SOFT, rings=8)

    # personal fields, right of the portrait
    fx = 252
    field(cv, fx, 262, "Surname", "REYEK", "sansb17")
    field(cv, fx, 306, "Given names", "TOMAS", "sansb17")
    field(cv, fx, 350, "Nationality", "VESSALIAN")
    field(cv, fx, 394, "Date of birth", "14 MAR 1988")
    field(cv, fx, 438, "Sex", "M")
    field(cv, fx + 70, 438, "Place of birth", "PORT ANSELM")
    field(cv, fx, 482, "Date of issue", "03 JUN 2021")
    field(cv, fx + 150, 482, "Date of expiry", "03 JUN 2031")

    # authority + signature
    field(cv, 40, 534, "Authority", "MINISTRY OF THE INTERIOR, PORT ANSELM",
          "sans13")
    draw_text(cv, 252, 592, "Holder's signature", "sans10", LABEL,
              tracking=0.6)
    pts = []
    for s in range(90):
        t = s / 89.0
        x = 258 + t * 190
        y = (622 + 9 * math.sin(t * 9.0) * (1 - t * 0.4)
             - 14 * math.exp(-((t - 0.18) ** 2) / 0.004)
             - 9 * math.exp(-((t - 0.58) ** 2) / 0.006))
        pts.append((x, y))
    for a, b in zip(pts, pts[1:]):
        cv.line(int(a[0]), int(a[1]), int(b[0]), int(b[1]), (30, 34, 60), 2)
    cv.line(252, 638, 470, 638, LABEL, 1)

    # ghost image (security reprint of the portrait, faded)
    small = bytearray()
    sw, sh = 62, 77
    for y in range(sh):
        for x in range(sw):
            sx = x * PORTRAIT_W // sw
            sy = y * PORTRAIT_H // sh
            i = (sy * PORTRAIT_W + sx) * 3
            small += raw[i:i + 3]
    cv.blit_rgb(bytes(small), sw, sh, 40, 588, alpha=110)
    draw_text(cv, 112, 622, "VES", "sansb14", GREEN_SOFT, tracking=2.0)
    draw_text(cv, 112, 640, "V4819207", "sans11", GREEN_SOFT)

    # observations - the telling detail of Vessalian paperwork
    draw_text(cv, 40, 714, "OBSERVATIONS", "sansb12", GREEN, tracking=1.2)
    cv.line(40, 722, 472, 722, GREEN_SOFT, 1)
    draw_text(cv, 40, 744,
              "The bearer may remain aboard vessels in Vessalian harbours",
              "sans12", INK)
    draw_text(cv, 40, 762,
              "without a shore pass while the harbour bell is rung at dusk.",
              "sans12", INK)
    draw_text(cv, 40, 788,
              "Report to the harbour office within 24 hours of arrival.",
              "sans12", INK)

    # perforated passport number down the left edge
    num = "V4819207"
    for i, ch in enumerate(num):
        draw_text(cv, 14, 300 + i * 26, ch, "mono17", (150, 148, 138))

    # machine-readable zone
    cv.rect(8, 908, 504, 1004, (238, 239, 228))
    name = "REYEK<<TOMAS"
    line1 = ("P<VES" + name).ljust(44, "<")
    num9 = "V4819207<"
    dob, exp, pers = "880314", "310603", "1029384756<<<<"
    line2 = (num9 + mrz_check(num9) + "VES" + dob + mrz_check(dob) + "M"
             + exp + mrz_check(exp) + pers + mrz_check(pers))
    comp = (line2[0:10] + line2[13:20] + line2[21:43])
    line2 = line2 + mrz_check(comp)
    draw_text(cv, 27, 946, line1, "mono17", INK)
    draw_text(cv, 27, 976, line2, "mono17", INK)


def visa_page(cv, rng):
    draw_text_center(cv, 768, 66, "VISAS", "sansb21", GREEN, tracking=7.0)
    cv.line(552, 80, 984, 80, GREEN, 1)
    draw_text_center(cv, 768, 100,
                     "This page is reserved for visas and endorsements.",
                     "sans10", LABEL)
    draw_text(cv, 972, 130, "5", "sans12", LABEL)

    # --- Drevania visa sticker, slightly askew
    visa = Canvas(300, 216, (247, 233, 226))
    visa.rect(0, 0, 300, 216, (247, 233, 226))
    for x in range(4, 296):
        visa.put(x, 4, (150, 90, 84))
        visa.put(x, 211, (150, 90, 84))
    for y in range(4, 212):
        visa.put(4, y, (150, 90, 84))
        visa.put(295, y, (150, 90, 84))
    draw_text_center(visa, 150, 34, "REPUBLIC OF DREVANIA", "sansb14",
                     (120, 52, 48), tracking=0.6)
    draw_text_center(visa, 150, 66, "VISA", "sansb26", (120, 52, 48),
                     tracking=6.0)
    visa.line(20, 78, 280, 78, (150, 90, 84), 1)
    draw_text(visa, 20, 100, "REYEK TOMAS", "sansb14", INK)
    draw_text(visa, 20, 126, "Entries  MULT", "sans12", INK)
    draw_text(visa, 20, 146, "Valid    01 SEP 2023 - 01 MAR 2024", "sans12",
              INK)
    draw_text(visa, 20, 166, "Type     VISITOR - 90 DAYS", "sans12", INK)
    draw_text(visa, 20, 192, "Issued at VELDRA PASS", "sans12", INK)
    cv.blit_rotated(visa, 700, 218, -2.0)
    fee = rect_stamp(["FEE PAID", "40 DREV"], "sansb12", "sansb12", RED_INK,
                     118, 52)
    blit_stamp(cv, fee, 822, 300, 9, rng, strength=190)

    # --- border stamps, in travel order
    s = rect_stamp(["PORT ANSELM INTL", "DEPARTED", "12 SEP 2023"],
                   "sansb12", "sans11", BLUE_INK, 196, 108, oval=True)
    blit_stamp(cv, s, 892, 190, 6, rng)
    s = rect_stamp(["DREVANIA", "VELDRA PASS", "ARRIVED 12 SEP 2023"],
                   "sansb14", "sans11", BLUE_INK, 218, 108)
    blit_stamp(cv, s, 668, 420, -4, rng)
    s = rect_stamp(["DREVANIA", "VELDRA PASS", "DEPARTED 19 SEP 2023"],
                   "sansb14", "sans11", BLUE_INK, 226, 108)
    blit_stamp(cv, s, 884, 452, 3, rng)
    s = rect_stamp(["KESTAVIA", "PORT SORREL FERRY", "ARRIVED 02 MAY 2024"],
                   "sansb12", "sans11", TEAL_INK, 216, 108, oval=True)
    blit_stamp(cv, s, 664, 596, -7, rng)
    s = rect_stamp(["KESTAVIA", "PORT SORREL", "DEPARTED 09 MAY 2024"],
                   "sansb12", "sans11", TEAL_INK, 216, 108, oval=True)
    blit_stamp(cv, s, 884, 640, 5, rng)
    s = rect_stamp(["PORT ANSELM INTL", "ARRIVED", "09 MAY 2024"],
                   "sansb12", "sans11", BLUE_INK, 196, 108, oval=True)
    blit_stamp(cv, s, 700, 786, -3, rng)
    s = rect_stamp(["HARBOUR DUES PAID", "12 TALAR - PORT ANSELM"],
                   "sansb12", "sans11", RED_INK, 240, 84)
    blit_stamp(cv, s, 856, 884, 2, rng, strength=190)


def main():
    rng = random.Random(20211121)
    cv = Canvas(W, H, (228, 226, 218))
    # the two pages
    cv.rect(8, 8, 504, 1016, PAPER)
    cv.rect(520, 8, 1016, 1016, PAPER)
    # faint printed frame on each page
    for (x0, x1) in ((8, 504), (520, 1016)):
        cv.line(x0 + 10, 18, x1 - 10, 18, (206, 204, 190), 1)
        cv.line(x0 + 10, 1006, x1 - 10, 1006, (206, 204, 190), 1)
    # spine shading
    for i in range(16):
        shade = 246 - i * 3
        cv.line(504 + i, 8, 504 + i, 1016, (shade, shade - 2, shade - 12), 1)
        cv.line(520 - i, 8, 520 - i, 1016, (shade, shade - 2, shade - 12), 1)
    guilloche(cv, 256, 330, 210, GREEN_SOFT, rings=44)
    data_page(cv, rng)
    visa_page(cv, rng)
    # gentle paper grain
    for _ in range(2600):
        x = rng.randrange(W)
        y = rng.randrange(H)
        d = rng.randrange(-5, 6)
        r, g, b = cv.get(x, y)
        cv.put(x, y, (max(0, min(255, r + d)), max(0, min(255, g + d)),
                      max(0, min(255, b + d))))
    out_dir = os.environ.get("MAKEFUN_OUTPUT_DIR", "/output")
    os.makedirs(out_dir, exist_ok=True)
    path = os.path.join(out_dir, "entry.png")
    size = write_png(cv, path)
    print(f"wrote {path} ({size} bytes)")


if __name__ == "__main__":
    main()
